#ifndef RASP_WBAES_H
#define RASP_WBAES_H

#include <stddef.h>
#include <stdint.h>

/* White-box AES-128 evaluator (design §8, Chow et al. 2002).
 *
 * Encrypts using only the lookup tables generated by the hardener (whitebox.py, emitted into
 * wbaes_tables.h). The AES key is never a contiguous literal in the binary — it is folded into the tables.
 *
 * SECURITY: these are the plain (unencoded) Chow tables. They do NOT resist key extraction on their own; the
 * internal encodings and mixing bijections that make white-box AES key-hiding are a deliberate next step (see
 * the repo TODO §8). Use this today for the correct, KAT-verified table architecture, not as key protection.
 *
 * Table layout matches whitebox.py exactly:
 *   type2 : 9*16*256 uint32, indexed type2[((r*16)+p)*256 + x]  (r in 0..8, p in 0..15)
 *   last  : 16*256 uint8,    indexed last[p*256 + x]
 * These are the addresses of RASP_WBAES_TYPE2 / RASP_WBAES_LAST in the generated header. */

void rasp_wbaes_encrypt_block(const uint32_t *type2, const uint8_t *last,
                              const uint8_t in[16], uint8_t out[16]);

/* AES-128 counter (CTR) mode over the white-box block function: keystream = E(nonce || counter_be32),
 * counter starting at 0. XORs `len` bytes of `in` into `out` (encryption and decryption are identical).
 * `nonce` is 12 bytes.
 *
 * The counter is 32-bit, so a single (nonce, key) pair is safe for up to 2^32 blocks (64 GiB). Beyond that
 * the counter wraps and the keystream repeats — callers must keep `len` under that bound and never reuse a
 * nonce with the same key. */
void rasp_wbaes_ctr(const uint32_t *type2, const uint8_t *last, const uint8_t nonce[12],
                    const uint8_t *in, size_t len, uint8_t *out);

#endif
